import openpyxl
from copy import copy

wb = openpyxl.load_workbook('output.xlsx')
ws = wb['Q']

# For each target block start row, the source block start row (5 rows each)
mapping = {3:23, 8:28, 13:3, 18:33, 23:18, 28:8, 33:13}

# Read all current values in A3:F37
cols = list(range(1,7))  # A..F
data = {}
for r in range(3,38):
    for c in cols:
        cell = ws.cell(row=r, column=c)
        data[(r,c)] = (cell.value, copy(cell._style))

# Build new layout
newdata = {}
for tstart, sstart in mapping.items():
    for i in range(5):
        sr = sstart + i
        tr = tstart + i
        for c in cols:
            newdata[(tr,c)] = data[(sr,c)]

# Write
for r in range(3,38):
    for c in cols:
        val, style = newdata[(r,c)]
        cell = ws.cell(row=r, column=c)
        cell.value = val
        cell._style = style

wb.save('output.xlsx')
print("saved")
EOF
python3 reorder.py
